class View:
    def __init__(self):
        self.rows = []  # stable rows list
        self.notes = {}  # job_id -> note
        self.loading = False
        self.error = None
        self.seq = 0          # monotonically increasing request id
        self.latest_id = None # id of the most recently begun request
        self.latest_rows = None # rows from the latest finished request

    def begin(self, query):
        self.seq += 1
        req_id = self.seq
        # clear loading errors
        self.loading = False
        self.error = None
        # store that this request is the latest begun
        self.latest_id = req_id
        # do not modify rows yet; keep existing rows
        return req_id

    def finish(self, request_id, rows):
        # only the latest begun request can update rows, once
        if self.latest_id is None:
            return False
        if request_id != self.latest_id:
            return False
        if self.latest_rows is not None:
            # duplicate finish for same latest request -> ignore
            return False
        # update rows once
        self.latest_rows = rows
        self.rows = rows  # rows reflect the latest valid result
        # keep loading False (already cleared) and no error
        return True

    def get_rows(self):
        # return copy of accepted rows (stable rows)
        return list(self.rows)

    def copy_accepted_rows(self):
        # same as get_rows, explicit copy
        return list(self.rows)

    def set_loading(self, loading):
        self.loading = loading

    def get_loading(self):
        return self.loading

    def set_error(self, error):
        self.error = error

    def get_error(self):
        return self.error

class View:
    def __init__(self):
        self.rows = []
        self.notes = {}
        self.loading = False
        self.error = None
        self.seq = 0
        self.latest_id = None   # id of most recently begun request
        self.latest_rows = None  # rows from the latest begun request if not finished yet

    def begin(self, query):
        self.seq += 1
        req_id = self.seq
        # clear loading errors
        self.loading = False
        self.error = None
        # set latest begun request
        self.latest_id = req_id
        # reset latest_rows because a new request starts
        self.latest_rows = None
        return req_id

    def finish(self, request_id, rows):
        # only the latest begun request can update rows, once
        if self.latest_id is None:
            return False
        if request_id != self.latest_id:
            return False
        if self.latest_rows is not None:
            # finish already called for this latest request -> duplicate
            return False
        # accept this finish
        self.latest_rows = rows
        self.rows = rows   # update rows
        return True

    def get_rows(self):
        return list(self.rows)

    def copy_accepted_rows(self):
        # explicit copy of accepted rows
        return list(self.rows)

    def set_loading(self, loading):
        self.loading = loading

    def get_loading(self):
        return self.loading

    def set_error(self, error):
        self.error = error

    def get_error(self):
        return self.error
